scripts.message-actions.barButtonPoint:
function barButtonPoint({ s, mid, tid }) {
  const m = document.querySelector(`${s.message}[data-mid="${CSS.escape(mid)}"]`);
  if (!m) return null;
  const r = m.getBoundingClientRect();
  const bars = [...document.querySelectorAll(s.actionBar)].filter((b) => b.offsetParent !== null);
  let best = null;
  let distance = 1e9;
  for (const b of bars) {
    const q2 = b.getBoundingClientRect();
    const d = Math.abs((q2.top + q2.bottom) / 2 - (r.top + Math.min(r.height, 40) / 2));
    if (d < distance) {
      distance = d;
      best = b;
    }
  }
  if (!best || distance > 120) return null;
  const btn = best.querySelector(`[data-tid="${CSS.escape(tid)}"]`);
  if (!btn || btn.offsetParent === null) return null;
  const q = btn.getBoundingClientRect();
  const x = q.left + q.width / 2;
  const y = q.top + q.height / 2;
  const hit = document.elementFromPoint(x, y);
  return hit && btn.contains(hit) ? { x, y } : null;
}

