scripts.page-state.installNotificationHook:
function installNotificationHook() {
  const w = window;
  if (w.__teamsHookInstalled) return "already";
  w.__teamsMsgs = w.__teamsMsgs || [];
  const capture = (title, body) => {
    try {
      w.__teamsMsgs.push({ title: String(title || ""), body: String(body || "") });
    } catch {
    }
  };
  try {
    const Original = window.Notification;
    const Wrapped = function(title, options) {
      capture(title, options && options.body);
      try {
        return new Original(title, options);
      } catch {
        return { close() {
        } };
      }
    };
    try {
      Wrapped.requestPermission = (cb) => {
        if (cb) cb("granted");
        return Promise.resolve("granted");
      };
    } catch {
    }
    try {
      Object.defineProperty(Wrapped, "permission", { get: () => "granted" });
    } catch {
    }
    window.Notification = Wrapped;
  } catch {
  }
  try {
    const proto = window.ServiceWorkerRegistration && ServiceWorkerRegistration.prototype;
    if (proto && proto.showNotification) {
      const show = proto.showNotification;
      proto.showNotification = function(title, options) {
        capture(title, options && options.body);
        return show.call(this, title, options);
      };
    }
  } catch {
  }
  try {
    const perms = navigator.permissions;
    const query = perms && perms.query ? perms.query.bind(perms) : null;
    if (query) {
      perms.query = ((d) => d && d.name === "notifications" ? Promise.resolve({ state: "granted", onchange: null }) : query(d));
    }
  } catch {
  }
  w.__teamsHookInstalled = true;
  return "installed";
}

scripts.page-state.makeVisible:
function makeVisible() {
  const w = window;
  if (w.__teamsVisible) return "already";
  try {
    Object.defineProperty(document, "visibilityState", { configurable: true, get: () => "visible" });
    Object.defineProperty(document, "hidden", { configurable: true, get: () => false });
    document.hasFocus = () => true;
    w.__teamsVisible = true;
    window.dispatchEvent(new Event("focus"));
    document.dispatchEvent(new Event("visibilitychange"));
    return "installed";
  } catch {
    return "failed";
  }
}

