scripts.page-state.uncoveredPoint:
function uncoveredPoint(sel) {
  const el = [...document.querySelectorAll(sel)].find((e) => {
    const r2 = e.getBoundingClientRect();
    return r2.width > 0 && r2.height > 0;
  });
  if (!el) return null;
  const r = el.getBoundingClientRect();
  for (const fy of [0.5, 0.85, 0.15]) {
    for (const fx of [0.5, 0.2, 0.8]) {
      const x = r.left + r.width * fx;
      const y = r.top + r.height * fy;
      const hit = document.elementFromPoint(x, y);
      if (hit && (hit === el || el.contains(hit))) return { x, y };
    }
  }
  return null;
}

scripts.page-state.watchInput:
function watchInput() {
  const w = window;
  if (w.__relayInputWatch) return "already";
  w.__relayInput = w.__relayInput || [];
  const note = (e) => {
    if (!e.isTrusted) return;
    const times = w.__relayInput = w.__relayInput || [];
    times.push(Date.now());
    if (times.length > 50) times.splice(0, times.length - 50);
  };
  for (const type of ["pointerdown", "keydown", "wheel"]) window.addEventListener(type, note, { capture: true, passive: true });
  w.__relayInputWatch = true;
  return "installed";
}

scripts.sign-in.signInPage:
function signInPage({ s, t, email = "" }) {
  const shown = (e) => {
    const r = e.getBoundingClientRect();
    const cs = getComputedStyle(e);
    return r.width > 0 && r.height > 0 && cs.visibility !== "hidden" && cs.display !== "none";
  };
  const label = (e) => (e.innerText || e.value || e.getAttribute("aria-label") || "").replace(/\s+/g, " ").trim();
  const free = (e) => {
    const r = e.getBoundingClientRect();
    for (const fy of [0.5, 0.25, 0.75]) {
      for (const fx of [0.5, 0.25, 0.75]) {
        const x = r.left + r.width * fx;
        const y = r.top + r.height * fy;
        const hit = document.elementFromPoint(x, y);
        if (hit && (hit === e || e.contains(hit)) && (hit.closest(s.clickable) ?? e) === e) return { x, y };
      }
    }
    return null;
  };
  const clickable = [...document.querySelectorAll(s.clickable)].filter(shown);
  const buttons = [...new Set(clickable.map((e) => label(e).slice(0, 40)).filter(Boolean))].slice(0, 30);
  const sessionLost = t.sessionLost.test(document.body && document.body.innerText || "");
  const signIns = clickable.filter((e) => t.signInButton.test(label(e)));
  const teams = { asks: sessionLost, found: signIns.length, at: sessionLost && signIns.length === 1 ? free(signIns[0]) : null };
  const untyped = ["hidden", "submit", "button", "checkbox", "radio", "image", "reset"];
  const fields = [...document.querySelectorAll(s.fields)].filter(shown).filter((f) => f.tagName !== "INPUT" || !untyped.includes((f.type || "text").toLowerCase()));
  if (fields.length) return { teams, microsoft: { asks: true, accounts: 0, account: null, buttons: 0, button: null }, buttons };
  const own = email.trim().toLowerCase();
  const word = new RegExp(`(^|[^a-z0-9._%+-])${own.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")}($|[^a-z0-9._%+-])`, "i");
  const named = own ? [...document.querySelectorAll(`${s.clickable},${s.accountTile}`)].filter(shown).filter((e) => (e.getAttribute("data-test-id") || "").toLowerCase() === own || e.matches(s.clickable) && word.test(e.innerText || "")) : [];
  const accounts = named.filter((e) => !named.some((o) => o !== e && e.contains(o)));
  const continues = clickable.filter((e) => t.microsoftButton.test(label(e)));
  return {
    teams,
    microsoft: {
      asks: false,
      accounts: accounts.length,
      account: accounts.length === 1 ? free(accounts[0]) : null,
      buttons: continues.length,
      button: continues.length === 1 ? free(continues[0]) : null
    },
    buttons
  };
}

scripts.tokens.readMsalEntries:
async function readMsalEntries(parts) {
  const b64 = (s) => {
    let t = s.replace(/-/g, "+").replace(/_/g, "/");
    while (t.length % 4) t += "=";
    return Uint8Array.from(atob(t), (c) => c.charCodeAt(0));
  };
  let cookie = null;
  const raw = document.cookie.split(";").map((c) => c.trim()).find((c) => c.startsWith("msal.cache.encryption="));
  if (raw) {
    try {
      cookie = JSON.parse(decodeURIComponent(raw.slice("msal.cache.encryption=".length)));
    } catch {
      cookie = null;
    }
  }
  let base = null;
  const out = [];
  for (let i = 0; i < localStorage.length; i++) {
    const key = localStorage.key(i) || "";
    const low = key.toLowerCase();
    if (!parts.every((p) => low.includes(p.toLowerCase()))) continue;
    let v = null;
    try {
      v = JSON.parse(localStorage.getItem(key) || "null");
    } catch {
      continue;
    }
    if (!v || typeof v !== "object") continue;
    if (typeof v.data === "string" && typeof v.nonce === "string") {
      if (!cookie?.key || v.id !== cookie.id) continue;
      try {
        base ??= await crypto.subtle.importKey("raw", b64(cookie.key), "HKDF", false, ["deriveKey"]);
        const context = key.split("|").slice(2).find((p) => /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(p)) || "";
        const derived = await crypto.subtle.deriveKey({ name: "HKDF", salt: b64(v.nonce), hash: "SHA-256", info: new TextEncoder().encode(context) }, base, { name: "AES-GCM", length: 256 }, false, ["decrypt"]);
        v = JSON.parse(new TextDecoder().decode(await crypto.subtle.decrypt({ name: "AES-GCM", iv: new Uint8Array(12) }, derived, b64(v.data))));
      } catch {
        continue;
      }
      if (!v || typeof v !== "object") continue;
    }
    if (typeof v.secret !== "string" || !v.secret) continue;
    out.push({ secret: v.secret, clientId: String(v.clientId || ""), homeAccountId: String(v.homeAccountId || ""), expiresOn: Number(v.expiresOn) || 0 });
  }
  return out;
}
